using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Options;

namespace Clovance.ApiService.Infrastructure.Auth.PasswordReset;

public static class PasswordResetServiceCollectionExtensions
{
    public static IServiceCollection AddPasswordReset(this IServiceCollection services, IConfiguration configuration)
    {
        services.Configure<PasswordResetOptions>(
            configuration.GetSection(PasswordResetOptions.SectionName));

        // Password reset tokens are generated by Identity's DataProtectorTokenProvider,
        // whose lifespan defaults to 24 hours. Wire it to Identity:PasswordReset so the
        // configured expiry (30 minutes) is actually enforced when the token is verified.
        services.AddOptions<DataProtectionTokenProviderOptions>()
            .Configure<IOptions<PasswordResetOptions>>((tokenProvider, passwordReset) =>
            {
                tokenProvider.TokenLifespan = TimeSpan.FromMinutes(passwordReset.Value.ExpirationMinutes);
            });

        return services;
    }
}
